// SUBMASK IDIOM: sub = (sub - 1) & m steps to the next smaller submask of m.
// Starting at m and stopping after 0 enumerates every submask exactly once.
vector<int> allSubmasks(int m) {
    vector<int> out;
    for (int sub = m; ; sub = (sub - 1) & m) {
        out.push_back(sub);
        if (sub == 0) break;              // test AFTER pushing, or 0 is skipped
    }
    return out;
}

// Sum over pairs (a, b) with a | b == FULL of value[a] & value[b].
// For each mask a, its partners b must cover FULL ^ a, so b is any superset of
// that -- equivalently, iterate a's submasks and use complements.
long long pairSum(const vector<long long>& value, int n) {
    int FULL = (1 << n) - 1;
    long long total = 0;
    for (int a = 0; a <= FULL; ++a) {
        int need = FULL ^ a;              // b must contain at least these bits
        int free_ = a;                    // b may additionally contain any submask of a
        for (int sub = free_; ; sub = (sub - 1) & free_) {
            int b = need | sub;
            total += value[a] & value[b];
            if (sub == 0) break;
        }
    }
    return total;
}
// 3^n SENTENCE: a mask with k set bits has 2^k submasks, and there are C(n,k)
// masks with k bits, so the total work is sum over k of C(n,k) * 2^k, which by
// the binomial theorem is (1 + 2)^n = 3^n. For n = 20 that is 3.5 * 10^9 -- at
// the edge; for n <= 18 it is comfortable.

int countSubarraysWithXor(const vector<int>& a, int k) {
    unordered_map<int,int> freq;
    freq[0] = 1;                       // the empty prefix, so whole-array matches count
    int prefix = 0, total = 0;
    for (int x : a) {
        prefix ^= x;
        // want prefix ^ earlier == k, i.e. earlier == prefix ^ k
        auto it = freq.find(prefix ^ k);
        if (it != freq.end()) total += it->second;
        ++freq[prefix];                // insert AFTER probing
    }
    return total;
}
// WHY XOR REPLACES SUBTRACTION: with sums, subarray = prefix[r] - prefix[l-1],
// so you look up prefix - k. XOR is its own inverse, so subarray =
// prefix[r] ^ prefix[l-1] and you look up prefix ^ k. Same prefix technique,
// different group operation.

vector<int> singleNumberIII(const vector<int>& a) {
    long long mix = 0;
    for (int x : a) mix ^= x;                 // mix == p ^ q

    // p != q so mix != 0. Its lowest set bit is a position where they DIFFER.
    int diffBit = (int)(mix & (-mix));

    int p = 0, q = 0;
    for (int x : a) {
        if (x & diffBit) p ^= x;              // bucket where that bit is 1
        else             q ^= x;              // bucket where it is 0
    }
    return {p, q};
}

