def single_number_iii(a: list) -> list:
    mix = 0
    for x in a:
        mix ^= x                     # mix == p ^ q

    # p != q so mix != 0. Its lowest set bit is a position where they DIFFER.
    diff_bit = mix & (-mix)

    p = q = 0
    for x in a:
        if x & diff_bit:
            p ^= x                   # bucket where that bit is 1
        else:
            q ^= x                   # bucket where it is 0
    return sorted([p, q])

