// Count ordered pairs (i, j) with value[i] & value[j] == 0.
// A partner of x must be a SUBMASK of ~x, so the answer per element is
// "how many values are submasks of ~x" -- exactly what SOS DP tabulates.
long long countPairsAndZero(const vector<int>& values, int B) {
    int SIZE = 1 << B;
    vector<long long> dp(SIZE, 0);
    for (int v : values) ++dp[v];              // dp[m] starts as the exact count

    // SOS: after bit b's pass, dp[m] counts values that are submasks of m
    // considering only bits 0..b. B passes over 2^B entries.
    for (int b = 0; b < B; ++b)
        for (int m = 0; m < SIZE; ++m)
            if (m & (1 << b)) dp[m] += dp[m ^ (1 << b)];

    long long total = 0;
    int FULL = SIZE - 1;
    for (int v : values) total += dp[FULL ^ v];   // partners are submasks of ~v
    return total;
}
// WHY NOT THE NAIVE WALK: iterating every submask of ~v costs 2^popcount(~v).
// If the values are SPARSE (few bits set), ~v is dense and that is 2^19 per
// element -- 10^6 * 500k operations. SOS is a flat 2*10^7 regardless of density.

int subarrayBitwiseORs(const vector<int>& a) {
    unordered_set<int> answer;      // every distinct OR seen anywhere
    unordered_set<int> frontier;    // distinct ORs of subarrays ENDING at i
    for (int x : a) {
        unordered_set<int> next{x};             // the single-element subarray
        for (int prev : frontier) next.insert(prev | x);
        frontier = move(next);
        answer.insert(frontier.begin(), frontier.end());
    }
    return (int)answer.size();
}
// WHY THE FRONTIER STAYS SMALL: extending a subarray leftward can only ADD bits,
// never remove them. So the ORs ending at i form a chain under inclusion, and a
// 30-bit value can gain a bit at most 30 times -- the frontier holds at most
// ~31 distinct values regardless of n. That is what makes this O(n * 30).

