def subarray_bitwise_ors(a: list) -> int:
    answer = set()        # every distinct OR seen anywhere
    frontier = set()      # distinct ORs of subarrays ENDING at i
    for x in a:
        frontier = {x} | {prev | x for prev in frontier}
        answer |= frontier
    return len(answer)
