// AVERAGE: (a + b) / 2 overflows when a and b are both near the limits.
// The identity below never forms the sum: the shared bits contribute once and
// the differing bits contribute half, rounded toward negative infinity.
int avgSafe(int a, int b) { return (a & b) + ((a ^ b) >> 1); }

// MAX / MIN without branches. Uses the sign of the difference -- but the
// difference itself can overflow, so this is only valid when a and b are known
// to be within INT_MAX of each other. Otherwise use std::max.
int maxNoBranch(int a, int b) {
    int diff = a - b;                       // GUARD: caller must ensure no overflow
    int sign = (diff >> 31);                // -1 if a < b, else 0
    return a - (diff & sign);
}
int minNoBranch(int a, int b) {
    int diff = a - b;
    int sign = (diff >> 31);
    return b + (diff & sign);
}

// ABS: the classic branchless form. UNDEFINED for INT_MIN, whose absolute value
// has no representation -- the caller must exclude it or widen the type.
int absNoBranch(int x) {
    int mask = x >> 31;                     // all ones if negative, else 0
    return (x ^ mask) - mask;               // two's complement negate when negative
}
long long absSafe(int x) { return x < 0 ? -(long long)x : (long long)x; }

