INT_MIN, INT_MAX = -2**31, 2**31 - 1


def _to_signed32(v: int) -> int:
    v &= 0xFFFFFFFF
    return v - (1 << 32) if v >> 31 else v


def avg_safe(a: int, b: int) -> int:
    """(a + b) // 2 without ever forming the sum: shared bits contribute once,
    differing bits contribute half. Rounds toward negative infinity."""
    return (a & b) + ((a ^ b) >> 1)


def max_no_branch(a: int, b: int) -> int:
    """GUARD: uses the sign of a - b, so the caller must ensure that difference
    fits in 32 bits. Otherwise use the built-in max."""
    diff = _to_signed32(a - b)
    sign = diff >> 31                 # -1 if a < b, else 0
    return a - (diff & sign)


def min_no_branch(a: int, b: int) -> int:
    diff = _to_signed32(a - b)
    sign = diff >> 31
    return b + (diff & sign)


def abs_no_branch(x: int) -> int:
    """UNDEFINED for INT_MIN in fixed width: its absolute value has no 32-bit
    representation. Use abs_safe when x may be INT_MIN."""
    mask = x >> 31                    # all ones if negative, else 0
    return _to_signed32((x ^ mask) - mask)


def abs_safe(x: int) -> int:
    """Widens instead of wrapping, so INT_MIN is handled correctly."""
    return -x if x < 0 else x
